// TestBuiltinMasksHideEachSecretForm: each platform's built-in list hides
// the secret of every form in secretForms and keeps the words around it.
func TestBuiltinMasksHideEachSecretForm(t *testing.T) {
	for _, f := range secretForms {
		res, _, err := CompileMasks(builtins[f.platform].Masks)
		if err != nil {
			t.Fatalf("%s: %v", f.platform, err)
		}
		if got := Mask(res, f.line); got != f.want {
			t.Errorf("%s, %s:\n%q\n got %q\nwant %q", f.platform, f.form, f.line, got, f.want)
		}
	}
}
